head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > P > editFormatPartialMask]<br/>마스킹 처리된 범위에 값을 입력할때 마지막으로 입력된 값의 표시 여부를 설정합니다.",
    "validation" : [                
        "editFormat 속성에 '{,}'(중괄호) 기호로 설정된 마스크 문자가 있고, 해당 범위에 입력값이 있을때 동작합니다.",
        "미설정 시 마스킹 범위의 마지막 입력값을 마스킹 문자로 표시합니다.",
        "true 설정 시 마스킹 범위의 마지막 입력값을 그대로 표시하고 다음 값이 입력되거나 포커스가 해제될때 마스킹 문자로 변경됩니다..",
        "false 설정 시 마스킹 범위의 마지막 입력값을 마스킹 문자로 표시합니다.",
    ]
}



scwin.onpageload = function () {
    // $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text_edit = function(target) {    
    let rtn = '';
    let tagName = target.tagName

    if (tagName !== "INPUT") {
        rtn = target.textContent
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    
    }
    else {
        rtn = target.value
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);   
    }    
}



